sections.source:
---
import BaseLayout from '../layouts/BaseLayout.astro';
import PageHeader from '../components/PageHeader.astro';
import Cta from '../components/Cta.astro';
import { SITE } from '../data/site';

const sections = [
  {
    id: 'collect',
    title: '1. Information We Collect',
    intro: 'We collect information you provide directly to us, information collected automatically, and information from service providers:',
    list: [
      ['Information you provide:', 'your name, address, email, phone number, property details, and any notes you share when you request a quote, schedule service, or contact us.'],
      ['Payment information:', 'billing details processed securely by our third-party payment processors. We do not store full card numbers on our servers.'],
      ['Automatically collected:', 'IP address, browser type, device information, pages viewed, and similar usage data gathered through cookies and analytics.'],
    ],
  },
  {
    id: 'use',
    title: '2. How We Use Information',
    intro: 'We use the information we collect to:',
    bullets: [
      'Provide, schedule, and perform pest control services and inspections;',
      'Prepare quotes, process payments, and send service reminders and follow-ups;',
      'Respond to your inquiries and provide customer support;',
      'Improve our website, services, and customer experience;',
      'Send you offers or updates where permitted (you may opt out at any time);',
      'Comply with legal obligations and enforce our agreements.',
    ],
  },
  {
    id: 'share',
    title: '3. How We Share Information',
    intro: 'We do not sell your personal information. We may share it only with:',
    list: [
      ['Service providers', 'who help us operate — such as scheduling, payment processing, analytics, and email delivery — under confidentiality obligations;'],
      ['Legal and safety', 'recipients when required by law, subpoena, or to protect our rights, customers, or the public;'],
      ['Business transfers', ', such as a merger or acquisition, in which case your information may be part of the transferred assets.'],
    ],
  },
  {
    id: 'cookies',
    title: '4. Cookies & Tracking',
    paragraphs: ['Our website uses cookies and similar technologies to remember your preferences, measure traffic, and improve performance. You can control or disable cookies through your browser settings; some features may not function properly if cookies are disabled.'],
  },
  {
    id: 'retention',
    title: '5. Data Retention',
    paragraphs: ['We retain personal information for as long as needed to provide our services, maintain service records and warranties, comply with legal and tax obligations, and resolve disputes. When information is no longer needed, we securely delete or anonymize it.'],
  },
  {
    id: 'security',
    title: '6. Data Security',
    paragraphs: ['We use reasonable administrative, technical, and physical safeguards to protect your information. However, no method of transmission or storage is completely secure, and we cannot guarantee absolute security.'],
  },
  {
    id: 'rights',
    title: '7. Your Rights & Choices',
    paragraphs: ['Depending on where you live, you may have the right to access, correct, delete, or restrict the use of your personal information, and to opt out of marketing communications. To exercise these rights, contact us using the details below. You may unsubscribe from marketing emails at any time using the link in each message.'],
  },
  {
    id: 'children',
    title: '8. Children’s Privacy',
    paragraphs: ['Our services are intended for adults. We do not knowingly collect personal information from children under 13. If you believe a child has provided us information, please contact us and we will delete it.'],
  },
  {
    id: 'changes',
    title: '9. Changes to This Policy',
    paragraphs: ['We may update this Privacy Policy from time to time. When we do, we will revise the “Last updated” date above. Significant changes will be communicated through our website or by other appropriate means.'],
  },
];

const toc = [
  ['#collect', '1. Information We Collect'],
  ['#use', '2. How We Use Information'],
  ['#share', '3. How We Share Information'],
  ['#cookies', '4. Cookies & Tracking'],
  ['#retention', '5. Data Retention'],
  ['#security', '6. Data Security'],
  ['#rights', '7. Your Rights & Choices'],
  ['#children', '8. Children’s Privacy'],
  ['#changes', '9. Changes to This Policy'],
  ['#contact', '10. Contact Us'],
];
---
<BaseLayout title="Privacy Policy — Hero Pest Control" description="How Hero Pest Control collects, uses, and protects your personal information. Read our Privacy Policy.">
  <PageHeader
    eyebrow="Legal"
    title="Privacy Policy"
    subtitle="How we collect, use, and protect the information you share with us."
    crumbs={[{ label: 'Home', href: '/' }, { label: 'Privacy Policy' }]}
  />

  <section class="bg-white py-16 sm:py-20">
    <div class="mx-auto max-w-3xl px-4">
      <p class="inline-flex items-center gap-2 rounded-full bg-brand-50 px-4 py-1.5 text-sm font-semibold text-brand-700">
        <svg class="h-4 w-4" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="4" width="18" height="18" rx="2"></rect><path d="M16 2v4M8 2v4M3 10h18"></path></svg>
        Last updated: June 7, 2026
      </p>

      <p class="mt-6 text-lg leading-relaxed text-slate-600">Hero Pest Control (“Hero,” “we,” “us,” or “our”) respects your privacy. This Privacy Policy explains what information we collect when you visit our website or use our services, how we use it, and the choices you have. By using our website or services, you agree to the practices described below.</p>

      <nav class="mt-8 rounded-2xl border border-slate-100 bg-mist p-6 shadow-soft" aria-label="On this page">
        <p class="text-sm font-bold uppercase tracking-wider text-slate-400">On this page</p>
        <ol class="mt-3 grid gap-2 text-sm font-semibold text-brand-700 sm:grid-cols-2">
          {toc.map(([href, label]) => <li><a href={href} class="hover:underline">{label}</a></li>)}
        </ol>
      </nav>

      <div class="mt-12 space-y-12">
        {
          sections.map((s) => (
            <section id={s.id} class="scroll-mt-28 reveal" x-intersect.once="$el.classList.add('shown')">
              <h2 class="font-display text-2xl font-extrabold tracking-tight">{s.title}</h2>
              {s.intro && <p class="mt-3 leading-relaxed text-slate-600">{s.intro}</p>}
              {s.paragraphs?.map((p) => <p class="mt-3 leading-relaxed text-slate-600">{p}</p>)}
              {s.bullets && (
                <ul class="mt-4 space-y-2 pl-5 leading-relaxed text-slate-600 [list-style:disc]">
                  {s.bullets.map((b) => <li>{b}</li>)}
                </ul>
              )}
              {s.list && (
                <ul class="mt-4 space-y-2 pl-5 leading-relaxed text-slate-600 [list-style:disc]">
                  {s.list.map(([strong, rest]) => (
                    <li><span class="font-semibold text-ink">{strong}</span> {rest}</li>
                  ))}
                </ul>
              )}
            </section>
          ))
        }

        <section id="contact" class="scroll-mt-28 reveal" x-intersect.once="$el.classList.add('shown')">
          <h2 class="font-display text-2xl font-extrabold tracking-tight">10. Contact Us</h2>
          <p class="mt-3 leading-relaxed text-slate-600">If you have questions about this Privacy Policy or how we handle your information, contact us:</p>
          <div class="mt-5 rounded-2xl border border-slate-100 bg-mist p-6 text-sm text-slate-600 shadow-soft">
            <p class="font-bold text-ink">{SITE.name}</p>
            <p class="mt-2 flex items-center gap-2"><svg class="h-4 w-4 text-brand-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M22 16.9v3a2 2 0 0 1-2.2 2 19.8 19.8 0 0 1-8.6-3.1 19.5 19.5 0 0 1-6-6 19.8 19.8 0 0 1-3.1-8.7A2 2 0 0 1 4.1 2h3a2 2 0 0 1 2 1.7c.1.9.4 1.8.7 2.7a2 2 0 0 1-.5 2.1L8.1 9.9a16 16 0 0 0 6 6l1.4-1.2a2 2 0 0 1 2.1-.5c.9.3 1.8.6 2.7.7a2 2 0 0 1 1.7 2Z"></path></svg> {SITE.phone}</p>
            <p class="mt-2 flex items-center gap-2"><svg class="h-4 w-4 text-brand-600" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><rect x="3" y="5" width="18" height="14" rx="2"></rect><path d="m3 7 9 6 9-6"></path></svg> {SITE.email}</p>
          </div>
        </section>
      </div>
    </div>
  </section>

  <Cta title="Ready for a pest-free home?" text="Book your free inspection today — no obligation." />
</BaseLayout>
